<?php
declare(strict_types=1);
namespace Liberu\SocialNetwork\Events\Actions;
use Illuminate\Support\Facades\DB; use InvalidArgumentException; use Liberu\SocialNetwork\Events\Contracts\EventsAuthorizer; use Liberu\SocialNetwork\Events\Models\Event; use Liberu\SocialNetwork\Profiles\Models\Profile;
final readonly class SetAttendance { public function __construct(private EventsAuthorizer $authorizer) {} public function handle(Profile $profile,Event $event,string $state): void { $this->authorizer->attend($profile,$event); if(!in_array($state,(array)config('social-network-events.attendance_states'),true)) throw new InvalidArgumentException('Attendance state is unsupported.'); if($state==='going'&&$event->capacity!==null&&DB::table('social_event_attendance')->where(['event_id'=>$event->getKey(),'state'=>'going'])->count()>=$event->capacity&&!DB::table('social_event_attendance')->where(['event_id'=>$event->getKey(),'profile_id'=>$profile->getKey(),'state'=>'going'])->exists()) throw new InvalidArgumentException('Event capacity has been reached.'); DB::table('social_event_attendance')->updateOrInsert(['event_id'=>$event->getKey(),'profile_id'=>$profile->getKey()],['state'=>$state,'updated_at'=>now(),'created_at'=>now()]); } }
